shell_commands:
cat << 'EOF' > patch.js
const fs = require('fs');
const file = 'src/orchestration/chatOrchestrator.test.ts';
let content = fs.readFileSync(file, 'utf8');

const newTest = `
    it('coerces a thrown string to an Error instance before calling onError', async () => {
      let receivedError: Error | undefined;
      const hooks: OrchestratorHooks = {
        onError: async (_session, error) => {
          receivedError = error;
        },
      };

      const provider: AIProvider = {
        // eslint-disable-next-line require-yield
        async *sendMessage() {
          throw 'string boom';
        },
        async generateStructured<T>() {
          return {} as T;
        },
      };

      const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
      let outcome: unknown;
      try {
        await orchestrator.processMessage(createSession('hello'));
        outcome = 'resolved without throwing';
      } catch (err) {
        outcome = err;
      }

      expect({
        outcome,
        isError: receivedError instanceof Error,
        message: receivedError?.message,
      }).toEqual({
        outcome: 'string boom',
        isError: true,
        message: 'string boom',
      });
    });
`;

content = content.replace("describe('onError', () => {", "describe('onError', () => {" + newTest);
fs.writeFileSync(file, content);
EOF
node patch.js
rm patch.js
